/* RE:LAND — dependency-free, accessible SPA. Backend owns all persistence/auth. */
'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const A=s=>{try{let u=new URL(s);return u.protocol==='https:'?E(u.href):'#'}catch{return '#'}};
const STATE={user:null,config:null,stats:null,districts:[],communities:[],news:[],posts:[],map:null,detail:null};
const main=document.querySelector('#main');
const HOST='/api';
const REGIONS=['전국','서울','경기','인천','부산','대구','대전','광주','울산','세종','강원','충북','충남','전북','전남','경북','경남','제주'];
const STAGES=['정비구역 지정','추진위원회','조합설립인가','사업시행인가','관리처분인가','이주·철거','착공','준공·이전고시'];
let searchTimer=null;
async function api(endpoint,options={}){
 const opt={credentials:'same-origin',...options};
 if(opt.body){opt.headers={'Content-Type':'application/json',...(opt.headers||{})}; if(typeof opt.body!=='string')opt.body=JSON.stringify(opt.body)}
 const res=await fetch(HOST+endpoint,opt); let json;try{json=await res.json()}catch{json={detail:'서버 응답을 처리하지 못했습니다.'}}
 if(!res.ok)throw new Error(typeof json.detail==='string'?json.detail:res.status+' 오류');return json;
}
function tip(message){const x=document.querySelector('#toast');x.textContent=message;x.classList.add('show');clearTimeout(x._t);x._t=setTimeout(()=>x.classList.remove('show'),3300)}
function formatDate(value){if(!value)return '날짜 미확인';let date=new Date(value);if(Number.isNaN(+date))return E(value.slice(0,25));return date.toLocaleDateString('ko-KR',{year:'numeric',month:'short',day:'numeric'})}
function compact(value){return new Intl.NumberFormat('ko-KR').format(value||0)}
function nav(page){return '/'+(page==='home'?'':page)}
function go(path){if(path===location.pathname){render();return}history.pushState({},'',path);render();scrollTo({top:0,behavior:'instant'})}
function headerPage(title,subtitle,kicker='RE:LAND SERVICE',dark=false){return `<section class="page-top ${dark?'dark':''}"><div class="shell"><div class="eyebrow">${E(kicker)}</div><h1>${title}</h1><p>${subtitle}</p></div></section>`}
function empty(icon,title,subtitle,cta=''){return `<div class="empty"><div class="empty-icon">${icon}</div><strong>${title}</strong><p>${subtitle}</p>${cta}</div>`}
function stripHTML(text){return String(text??'').replace(/<[^>]*>/g,'').replace(/\s+/g,' ').slice(0,500)}
function modal(html){const n=document.querySelector('#modal');n.innerHTML=`<div class="modal" role="dialog" aria-modal="true">${html}</div>`;n.classList.remove('hidden');document.body.style.overflow='hidden';n.querySelector('input,button')?.focus()}
function closeModal(){const n=document.querySelector('#modal');n.classList.add('hidden');n.innerHTML='';document.body.style.overflow=''}
function modalTitle(title){return `<div class="modal-header"><h2>${title}</h2><button class="modal-close" data-action="close-modal" aria-label="닫기">×</button></div>`}
function loginModal(){modal(`${modalTitle('리랜드에 오신 것을 환영해요')}<p>Google 계정으로 동네를 팔로우하고 질문과 소식을 공유하세요. 로그인만으로 법적 조합원 자격이 인증되지는 않습니다.</p><div id="google-login" class="google-login-wrap"></div><div class="modal-divider">${STATE.config?.google_client_id?'또는 데모 체험':'로그인 설정 안내'}</div>${STATE.config?.demo_enabled?`<button class="btn btn-primary" style="width:100%" data-action="demo-login">체험 계정으로 시작하기 (로컬 전용)</button>`:''}${!STATE.config?.google_client_id?`<div class="notice warn">현재 Google OAuth 클라이언트 ID가 설정되지 않았습니다. 관리자에게 <code>GOOGLE_CLIENT_ID</code> 등록을 요청하세요.</div>`:''}<p style="margin-top:18px">개인정보는 서비스 이용에 필요한 범위에서 처리합니다. <a class="inline-link" href="/privacy" data-nav="privacy">개인정보 안내 보기</a></p>`);
 if(STATE.config?.google_client_id){
  let attempt=0;const setup=()=>{attempt++;if(window.google?.accounts?.id){try{google.accounts.id.initialize({client_id:STATE.config.google_client_id,callback:async result=>{try{const res=await api('/auth/google',{method:'POST',body:{credential:result.credential}});STATE.user=res.user;closeModal();updateLogin();tip('Google 계정으로 로그인했습니다.');render()}catch(err){tip(err.message)}}});google.accounts.id.renderButton(document.querySelector('#google-login'),{theme:'outline',size:'large',shape:'pill',text:'continue_with',width:320})}catch(err){tip('Google 로그인 버튼을 초기화하지 못했습니다.')}}else if(attempt<15)setTimeout(setup,350);else{document.querySelector('#google-login').textContent='Google 로그인 스크립트를 불러오지 못했습니다.'}};setup();
 }
}
function updateLogin(){document.querySelector('.login-button').innerHTML=STATE.user?`<span class="g-symbol">${E(STATE.user.nickname[0])}</span><span>${E(STATE.user.nickname)}</span>`:'<span class="g-symbol">G</span><span>구글로 시작하기</span>'}
function ensureAuth(){if(STATE.user)return true;loginModal();return false}
async function initialize(){try{const [config,auth]=await Promise.all([api('/config'),api('/auth/me')]);STATE.config=config;STATE.user=auth.user;updateLogin()}catch(e){tip('서버를 연결하지 못했습니다. 실행 방법을 확인하세요.')}render()}
function setActive(page){document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page && a.closest('.main-nav'))});document.querySelector('.header').classList.remove('menu-open')}
async function render(){if(STATE.map){try{STATE.map.remove()}catch{}STATE.map=null};let path=decodeURI(location.pathname).replace(/\/$/,'')||'/';const parts=path.split('/').filter(Boolean);const page=parts[0]||'home';setActive(page);main.innerHTML='<div class="loading-screen"><div class="loading-dot"></div>정보를 불러오는 중입니다</div>';
 try{switch(page){case 'home':await homePage();break;case 'map':await mapPage();break;case 'district':await districtPage(+parts[1]);break;case 'community':await communityPage(parts[1]?+parts[1]:null);break;case 'feed':await feedPage();break;case 'post':await postPage(+parts[1]);break;case 'news':await newsPage();break;case 'guide':await guidePage();break;case 'experts':await expertsPage();break;case 'directory':await directoryPage();break;case 'expert':await expertDetailPage(+parts[1]);break;case 'columns':await columnsPage();break;case 'column':await columnPage(+parts[1]);break;case 'shorts':await shortsPage();break;case 'partners':await partnerPage();break;case 'profile':await profilePage();break;case 'sources':await sourcesPage();break;case 'privacy':await privacyPage();break;default:main.innerHTML=headerPage('페이지를 찾을 수 없어요','요청하신 주소를 확인해주세요.')+'<div class="shell page-body"><a class="btn btn-primary" href="/" data-nav="home">홈으로 이동</a></div>'}}
 catch(err){main.innerHTML=headerPage('정보를 불러오지 못했습니다','서버 연결과 데이터 상태를 확인해주세요.')+`<div class="shell page-body">${empty('⚠️','화면을 표시할 수 없어요',E(err.message),'<button class="btn btn-primary" data-action="reload">다시 시도</button>')}</div>`}
}
function statsHTML(s){return `<div class="stats-strip"><div class="shell stats-inner"><div class="stat"><div class="stat-icon">▦</div><div><strong>1,566<small>행</small></strong><p>전국 공개 원본 목록 <small>2026.5 기준</small></p></div></div><div class="stat"><div class="stat-icon">♧</div><div><strong>${compact(s?.districts)}<small>건</small></strong><p>앱으로 가져온 실제 구역</p></div></div><div class="stat"><div class="stat-icon">♧</div><div><strong>${compact(s?.communities)}<small>개</small></strong><p>동네 커뮤니티 <small>예시 포함</small></p></div></div><div class="stat"><div class="stat-icon">◈</div><div><strong>${compact(s?.news)}<small>건</small></strong><p>연결된 뉴스 피드 항목</p></div></div></div></div>`}
function communityCard(c,i){return `<article class="community-card"><a href="/community/${c.id}" data-nav="community"><div class="community-cover c${i%4+1}"><span class="community-cover-label">${E(c.region)}</span></div><div class="community-content"><div class="pill gray">${E(c.region)}</div><h3>${E(c.name)}</h3><p>${E(c.description)}</p><div class="community-bottom"><span>♧ 관심 회원 ${compact(c.followers)}</span><b>둘러보기 ↗</b></div></div></a></article>`}
function placeRow(d,i){return `<button class="place-row" data-action="district" data-id="${d.id}"><span class="place-number">${String(i+1).padStart(2,'0')}</span><span class="place-info"><strong>${E(d.name)}</strong><small>${E(d.province)} · ${d.demo?'시연용 지역 허브':E(d.stage)}</small></span><span class="arrow">↗</span></button>`}
async function homePage(){const [stats,districts,communities,news]=await Promise.all([api('/stats'),api('/districts?limit=8'),api('/communities'),api('/news?limit=3')]);Object.assign(STATE,{stats,districts:districts.items,communities:communities.items,news:news.items});
 main.innerHTML=`<section class="hero"><div class="shell hero-inner"><div class="hero-content"><div class="hero-badge"><i class="glow"></i> RE:LAND COMMUNITY ATLAS · 대한민국 정비사업 정보 플랫폼</div><h1>우리 동네의 변화,<br><em>함께 만들어가는 내일.</em></h1><p class="hero-sub">전국 재개발·재건축 정보부터 이웃들의 생생한 이야기까지.<br>지도 위에서 발견하고, 사람과 연결되는 새로운 도시의 시작.</p><form class="hero-search" id="hero-search"><span>⌕</span><input aria-label="지역 또는 구역 검색" name="q" placeholder="지역명, 구역명으로 찾아보세요. 예: 서울, 부산" maxlength="80"><button type="submit">지도에서 검색 ↗</button></form><div class="hero-tags"><span>인기 지역</span>${['서울','경기','인천','부산'].map(x=>`<button data-action="search-region" data-value="${x}">${x} ↗</button>`).join('')}</div></div></div><div class="hero-float"><div class="round-icon">⌁</div><div><strong>Our neighborhood, together.</strong><small>변화를 한눈에, 소통은 더 가깝게</small></div></div></section>${statsHTML(stats)}
 <section class="section" id="studio-spotlight" style="background:#eff5f0"><div class="shell"><div class="section-header"><div><span class="eyebrow">RE:LAND LEGAL JOURNAL</span><h2>우리 동네 변화, 법률 전문가의 관점으로</h2><p>재개발 법률 초안 120편·국가법령정보센터 원문·검토된 전문가 연결·Shorts를 한곳에서.</p></div><a class="inline-link" href="/columns" data-nav="columns">칼럼 전체 보기 ↗</a></div><div class="studio-home-feature"><div class="studio-home-photo"><img loading="lazy" src="/static/assets/legal-office-source.webp" alt="재개발 법률 정보를 다루는 회의실 콘셉트 실사 이미지 · AI 생성 · 실제 사무소 사진 아님"><span class="photo-disclaimer">AI CONCEPT · NOT A REAL FIRM</span></div><div class="studio-home-copy"><span class="studio-kicker">120 ORIGINAL EDITORIAL DRAFTS</span><h3>조합설립부터 관리처분,<br>서류 한 장까지 근거를 따라갑니다.</h3><p>조문 원문은 법제처에 연결됩니다. 법률전문가 감수 전 편집 초안이며 실제 사건의 법률 자문을 대신하지 않습니다.</p><div class="studio-links"><a class="btn btn-primary" href="/columns" data-nav="columns">재개발 법률 저널 →</a><a class="btn btn-soft" href="/directory" data-nav="directory">전문가 디렉터리 →</a><a class="btn btn-soft" href="/shorts" data-nav="shorts">Shorts 채널 →</a><a class="btn btn-soft" href="/kang/">강실장 교육 블로그 →</a></div></div></div></div></section>
 <section class="section"><div class="shell"><div class="section-header"><div><span class="eyebrow">EXPLORE OUR CITY</span><h2>지도 위에서 만나는 우리 동네</h2><p>전국 지역을 누르면 공공데이터포털 정비구역 정보가 표시됩니다.</p></div><a class="inline-link" href="/map" data-nav="map">전국 지도 전체보기 <b>↗</b></a></div><div class="map-feature"><div class="map-shell"><div class="mini-map"><div class="map-grid-road"></div><div class="map-water"></div><button class="map-pin primary" style="top:35%;left:62%" data-action="search-region" data-value="서울">● 서울</button><button class="map-pin" style="top:51%;left:33%" data-action="search-region" data-value="인천">● 인천</button><button class="map-pin" style="top:69%;left:69%" data-action="search-region" data-value="경기">● 경기</button><div class="map-top-label">전국 권역 지도 미리보기</div><div class="map-caption"><div><strong>우리 지역 정보를 더 자세히</strong><br><span>국토교통부 공공데이터(정비구역 목록) · 지도는 시·도 기준점</span></div><a class="btn btn-primary btn-small" href="/map" data-nav="map">지도 열기 →</a></div></div></div><div class="map-side"><div class="side-heading"><h3>지역 바로가기</h3><span class="pill">시연용 허브</span></div>${districts.items.slice(0,3).map(placeRow).join('')}<div class="soft-info">ⓘ 공공데이터를 가져오기 전에는 행정 지역 중심점만 표시하며, 실제 재개발 구역이나 경계라고 주장하지 않습니다.</div></div></div></div></section>
 <section class="section" style="background:#f1f6ef"><div class="shell"><div class="section-header"><div><span class="eyebrow">ALL IN ONE PLATFORM</span><h2>복잡한 재개발 정보, 한곳에서</h2><p>정보를 찾는 순간부터 이웃과 함께 결정하는 순간까지.</p></div></div><div class="grid-4">${[
 ['🗺️','전국 재개발 지도','정비사업 지역별 정보, 추진단계와 출처를 한눈에 살펴보세요.','map'],['💬','우리 동네 커뮤니티','동네 친구들과 질문하고 소식과 경험을 나눠보세요.','community'],['📰','실시간 뉴스룸','새로운 정책, 정비사업 소식을 원문 링크 기반으로 확인하세요.','news'],['⚖️','법률·전문가 연결','도시정비법 기초 안내부터 전문가 상담 접수까지.','experts']].map(f=>`<article class="feature-card"><div class="feature-icon">${f[0]}</div><h3>${f[1]}</h3><p>${f[2]}</p><a class="inline-link" href="/${f[3]}" data-nav="${f[3]}">살펴보기 →</a></article>`).join('')}</div></div></section>
 <section class="section"><div class="shell"><div class="section-header"><div><span class="eyebrow">NEIGHBORHOOD CONNECTIONS</span><h2>우리 동네, 함께 연결되는 공간</h2><p>정보가 모이고, 이야기가 쌓이며, 이웃이 연결됩니다.</p></div><a class="inline-link" href="/community" data-nav="community">모든 커뮤니티 보기 ↗</a></div><div class="grid-4">${communities.items.slice(0,4).map(communityCard).join('')}</div></div></section>
 <section class="section" style="background:#f5f7f1"><div class="shell"><div class="section-header"><div><span class="eyebrow">URBAN REGENERATION NEWS</span><h2>놓치면 아쉬운 재개발 소식</h2><p>정책·법률·우리 동네 이슈를 뉴스 원문 출처와 함께 제공합니다.</p></div><a class="inline-link" href="/news" data-nav="news">뉴스룸 전체보기 ↗</a></div><div class="news-layout"><div class="news-highlight"><span>RE:LAND ORIGINAL GUIDE</span><h3>정비사업의 첫걸음,<br>우리 동네는 지금 어디쯤일까요?</h3><p>구역 지정부터 준공까지, 중요한 절차와 서류를 한눈에 살펴보세요. 실제 단계는 반드시 공식 고시를 확인해야 합니다.</p><a href="/guide" data-nav="guide">정비사업 기초 안내 읽기 →</a></div><div class="news-list">${news.items.length?news.items.slice(0,3).map((n,i)=>`<a class="news-item" href="${A(n.url)}" target="_blank" rel="noopener noreferrer"><span class="news-number">0${i+1}</span><span><h4>${E(n.title)}</h4><small>${E(n.source)} · ${E(n.published)}</small></span></a>`).join(''):`<div style="padding:30px 0"><span class="pill orange">뉴스 피드 연결 대기</span><h3 style="font-size:18px;margin:14px 0">검증된 새 뉴스가 아직 없습니다.</h3><p class="muted" style="font-size:12px">서버가 공개 RSS를 가져오면 기사 제목과 원문 링크가 나타납니다. 임의의 뉴스는 만들지 않습니다.</p><a href="/news" data-nav="news" class="inline-link">뉴스 제공처 확인하기 →</a></div>`}</div></div></div></section>
 <section class="section"><div class="shell"><div class="cta-panel"><div><span class="eyebrow" style="color:#cdeba8">JOIN OUR COMMUNITY</span><h2>우리 동네에 관심이 생겼나요?</h2><p>Google 계정으로 이웃을 팔로우하고 직접 질문을 남겨보세요. 동네의 이야기는 연결에서 시작됩니다.</p></div><button class="btn btn-accent" data-action="${STATE.user?'my-profile':'login'}">${STATE.user?'내 프로필 보기':'Google 계정으로 시작하기'} →</button></div></div></section>`;
}
function mapFallback(items,elementId){const elem=document.getElementById(elementId);if(!elem)return;const nonNull=items.filter(x=>x.lat!=null&&x.lon!=null);elem.innerHTML=`<div class="mini-map"><div class="map-grid-road"></div><div class="map-water"></div><div class="map-top-label">지도 미리보기 · 축척·경계 비정확</div>${nonNull.slice(0,60).map((d,i)=>{const x=Math.max(7,Math.min(89,((d.lon-124.5)/8)*90+5)),y=Math.max(16,Math.min(86,((39-d.lat)/7)*76+10));return `<button class="map-pin ${i===0?'primary':''}" style="left:${x}%;top:${y}%" data-action="district" data-id="${d.id}" title="지역 중심점 (경계 아님)">${E(d.city||d.name)}</button>`}).join('')}<div class="map-caption"><strong>배경은 장식용 지도입니다</strong><span>실제 지도를 이용하려면 인터넷 연결이 필요해요.</span></div></div>`}
function leafletMap(items,elementId,zoom=7,center=[36.2,127.75]){const elem=document.getElementById(elementId);if(!elem)return;
 // Leaflet is optional: the fallback works even if CDN assets are inaccessible.
 if(!window.L){mapFallback(items,elementId);return}
 elem.innerHTML='<div class="leaflet-map" id="leaflet-' +elementId+'"></div><div class="map-top-label">● 정확한 경계 아님 · 지역 기준점</div>';
 STATE.map=L.map('leaflet-'+elementId,{scrollWheelZoom:false}).setView(center,zoom);
 L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap contributors'}).addTo(STATE.map);
 let groups={};for(const d of items){if(!Number.isFinite(+d.lat)||!Number.isFinite(+d.lon)||d.lat===null||d.lon===null)continue;const key=(+d.lat).toFixed(3)+':'+(+d.lon).toFixed(3);if(!groups[key])groups[key]=[];groups[key].push(d)}
 for(const group of Object.values(groups)){const d=group[0];let label=group.length>1?`${d.city} · ${group.length}건`:d.demo?d.city:d.name;const marker=L.marker([d.lat,d.lon],{icon:L.divIcon({className:'leaflet-div-icon',html:`<span class="leaflet-marker-reland">${E(label.slice(0,16))}</span>`,iconSize:[30,32]})}).addTo(STATE.map);
 marker.bindPopup(`<strong>${E(group.length>1?d.city:d.name)}</strong><p>${group.length>1?'이 좌표에 '+group.length+'개 목록이 모여 있습니다.':'위치는 '+(d.precision==='boundary_polygon'?'경계 자료 기반 좌표':d.precision==='exact'?'구역 좌표':'지역 중심점')+'으로 표시됩니다.'}</p><a href="/district/${d.id}" class="popup-link">상세 보기 →</a>`);
 marker.on('popupopen',()=>{const link=document.querySelector('.popup-link');if(link)link.addEventListener('click',e=>{e.preventDefault();go('/district/'+d.id)})});
 }
 setTimeout(()=>STATE.map?.invalidateSize(),100);
}
function mapResultRow(d){return `<div class="result-row" data-action="district" data-id="${d.id}" role="button" tabindex="0"><div class="result-meta"><span class="pill ${d.demo?'orange':'navy'}">${d.demo?'시연 지역':E(d.kind)}</span><small>${E(d.province)}</small></div><h4>${E(d.name)}</h4><small>${d.demo?'실제 구역 데이터 연결 전':E(d.stage)} · ${d.precision==='boundary_polygon'?'검증 등록된 경계':d.precision==='exact'?'상세좌표':'행정구역 기준점'}</small></div>`}
async function mapPage(){let params=new URLSearchParams(location.search);let query=params.get('q')||'',region=params.get('region')||'전국',kind=params.get('kind')||'전체',stage=params.get('stage')||'전체';let data=await api('/districts?'+new URLSearchParams({q:query,region,kind,stage,limit:'2000'}));STATE.districts=data.items;
 main.innerHTML=headerPage('우리 동네 정비사업 지도','지도로 지역별 변화를 발견하세요. 위치가 확인되지 않은 데이터는 시군구 대표점으로 표시됩니다.','REDEVELOPMENT ATLAS')+`<div class="shell page-body"><form class="filters" id="map-filter"><input class="filter-input" name="q" value="${E(query)}" aria-label="구역명 또는 지역명" placeholder="⌕  지역명 / 구역명 검색"><select class="filter-select" name="region" aria-label="지역 선택">${REGIONS.map(x=>`<option ${region===x?'selected':''}>${x}</option>`).join('')}</select><select class="filter-select" name="kind" aria-label="사업유형"><option>전체</option>${['재개발사업','재건축사업','주거환경개선사업','지역 안내'].map(x=>`<option ${kind===x?'selected':''}>${x}</option>`).join('')}</select><select class="filter-select" name="stage" aria-label="추진단계"><option>전체</option>${STAGES.map(x=>`<option ${stage===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn btn-primary" type="submit">검색하기</button></form><div class="map-page-layout"><div id="full-map" class="full-map" aria-label="전국 정비사업 지도"></div><aside class="map-results"><div class="map-results-head"><strong>검색 결과 ${compact(data.items.length)}건</strong><span class="pill">실제 데이터 ${compact(data.verified_data_rows)}건</span></div>${data.items.length?data.items.slice(0,100).map(mapResultRow).join(''):empty('🔍','검색 결과가 없어요','검색어 또는 필터를 변경해 보세요.')}</aside></div><div class="notice warn">⚑ 지도에 표시된 시연용 지역 허브는 재개발 확정 지역이 아닙니다. 공공데이터 원본에도 위경도·경계가 없어 좌표 검증 없이 정확한 구역 경계로 표시하지 않습니다. <a class="inline-link" href="/sources" data-nav="sources">데이터 출처·연동 안내 ↗</a></div></div>`;
 leafletMap(data.items,'full-map',region==='서울'?10:7,region==='서울'?[37.5665,126.978]:[36.25,127.75]);
 // Spatial shapes are drawn only when independently reviewed WGS84 GeoJSON exists.
 try {const boundaries=await api('/map/boundaries?limit=1000');
   const selected=new Set(data.items.map(x=>x.id));
   if(window.L&&STATE.map&&boundaries.items.length){
     for(const item of boundaries.items){if(!selected.has(item.district_id))continue;
       const layer=L.geoJSON(item.feature,{style:{color:'#206a57',weight:2,fillColor:'#66bba0',fillOpacity:.22}}).addTo(STATE.map);
       layer.bindPopup(`<strong>확인된 폴리곤 #${item.district_id}</strong><p>출처 기준일: ${E(item.source_date)}</p><a href="/district/${item.district_id}" data-nav="district">상세 정보 보기</a>`);
     }
     let notice=document.querySelector('#full-map .map-top-label');if(notice)notice.textContent='● 출처 검증 등록된 경계 + 지역 기준점 혼합 표시';
   }
 }catch(err){console.warn('GeoJSON 레이어를 불러오지 못했습니다.',err)}
}
async function districtPage(id){
 const d=await api('/districts/'+id);STATE.detail=d;
 let watch=false; if(STATE.user&&!d.demo){try{watch=(await api('/my/dashboard')).watches.some(x=>x.id===id)}catch{}}
 let geometry=null; if(d.precision==='boundary_polygon'){try{geometry=await api('/districts/'+id+'/geometry')}catch{}}
 main.innerHTML=headerPage(E(d.name),`${E(d.province)} · ${E(d.city)} | ${d.demo?'시연용 지역 허브':E(d.kind)}`,'DISTRICT PROFILE')+`<div class="shell page-body"><div class="details-grid"><div><div class="panel"><div class="section-header"><div><span class="pill ${d.demo?'orange':'navy'}">${d.demo?'지역 허브 / 실데이터 아님':E(d.kind)}</span><h3 style="margin-top:12px">정비사업 기본 정보</h3></div><a class="inline-link" href="/map" data-nav="map">← 지도로 돌아가기</a></div><div class="detail-facts">${[['지역',d.province+' '+d.city],['진행 단계',d.stage],['사업 유형',d.kind],['예정 공급 세대',d.households?d.households+'세대':'자료 미제공'],['사업시행자',d.operator||'자료 미제공'],['자료 기준일',d.source_date||'원본 확인 필요'],['위치 정밀도',d.precision==='boundary_polygon'?'경계 폴리곤 별도 등록됨':d.precision==='exact'?'좌표 보유':'행정 중심점 / 정확 경계 아님'],['데이터 상태',d.demo?'예시 / 공식 구역 아님':'공공 데이터 가져오기 완료']].map(x=>`<div class="fact"><label>${E(x[0])}</label><strong>${E(x[1])}</strong></div>`).join('')}</div></div><div class="panel"><h3>이 구역 관심등록</h3>${d.demo?`<p class="muted">시연용 지역 허브는 실제 구역이 아니므로 관심 등록할 수 없습니다.</p>`:`<p class="muted">관심 구역의 자료 변경 내역을 내 프로필에서 확인하세요. 문자·푸시 알림은 별도 기능입니다.</p><button class="btn ${watch?'btn-soft':'btn-primary'}" data-action="watch-district" data-id="${d.id}">${watch?'✓ 관심 구역 등록됨 · 취소':'☆ 이 구역 관심등록'}</button>`}</div><div class="panel"><h3>재개발 진행 단계 안내</h3><div class="progress-track">${STAGES.map((s,i)=>`<div class="progress-step ${d.stage===s?'active':''}">${String(i+1).padStart(2,'0')}<br>${s}</div>`).join('')}</div><div class="notice">실제 정비사업의 절차는 사업방식 및 법령 개정에 따라 달라질 수 있습니다. 단계 표시는 공공 데이터 기준 시점의 참고정보이며 현행 고시로 확인해야 합니다.</div></div></div><aside><div class="panel"><h3>공식 자료 확인하기</h3><p class="muted" style="font-size:12px">확정적인 권리판단에 앞서 최신 공고문과 구역 경계를 확인하세요.</p><a class="source-link" href="${A(d.source_url||'https://www.data.go.kr/data/15160169/fileData.do')}" target="_blank" rel="noopener noreferrer">↗ 이 데이터의 공식 출처</a><a class="source-link" href="https://cleanup.seoul.go.kr/" target="_blank" rel="noopener noreferrer">↗ 서울시 정비사업 정보몽땅</a><a class="source-link" href="https://www.law.go.kr/" target="_blank" rel="noopener noreferrer">↗ 국가법령정보센터</a></div>${geometry?`<div class="side-card"><h3>확인 등록된 구역 경계</h3><p>경계 원본 일자: ${E(geometry.source_date)}. 원본과 현재 효력은 별도로 확인하세요.</p><a class="inline-link" target="_blank" rel="noopener noreferrer" href="${A(geometry.source_url)}">경계 출처 열기 ↗</a><div id="detail-boundary-map" style="height:210px;margin-top:15px;border-radius:12px;overflow:hidden"></div></div>`:''}<div class="side-card"><h3>이 지역 이웃들과 소통하기</h3><p>질문과 지역 소식을 커뮤니티에 공유해 보세요. 법적 조합 공식 채널과는 별개입니다.</p><a class="btn btn-primary" style="width:100%" href="/community" data-nav="community">커뮤니티 둘러보기 ↗</a></div><div class="side-card"><h3>법률적으로 궁금하다면?</h3><p>권리 산정, 이주·보상, 조합 운영 등에 대한 상담 접수 창구입니다.</p><a class="btn btn-soft" href="/experts" data-nav="experts">전문가 상담 문의 →</a></div></aside></div></div>`;
 if(geometry&&window.L){try{const map=L.map('detail-boundary-map',{scrollWheelZoom:false});
   L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap'}).addTo(map);
   const shape=L.geoJSON(geometry.feature,{style:{color:'#19694e',weight:3,fillOpacity:.22}}).addTo(map);
   map.fitBounds(shape.getBounds(),{padding:[18,18]});STATE.map=map;
 }catch(e){console.warn('상세 폴리곤 렌더링 실패',e)}}
}
async function communityPage(id){if(id){let [data,postData]=await Promise.all([api('/communities/'+id),api('/posts?community_id='+id)]);let c=data.item;main.innerHTML=headerPage(E(c.name),E(c.description),'OUR NEIGHBORHOOD',true)+`<div class="shell page-body"><div class="feed-layout"><div><div class="community-hero"><span class="pill">${c.official?'운영자 확인된 공식 조직':'비공식 주민 커뮤니티'}</span><h1>${E(c.name)}</h1><p>${E(c.region)} · 관심 회원 ${compact(data.followers)}명 · 게시글 ${postData.items.length}건</p><button class="btn btn-accent" data-action="follow" data-id="${id}">${data.following?'✓ 팔로우 중 · 취소':'＋ 이 커뮤니티 팔로우'}</button></div><div class="notice">이곳은 주민 교류 공간입니다. 팔로우만으로 법적 조합원 신분이 인증되거나 조합의 공식 의결·통지 기능이 발생하지 않습니다.</div><div class="feed-create"><div class="user-avatar">✎</div><button data-action="write-post" data-community="${id}">이 동네에 질문이나 이야기를 남겨보세요...</button></div>${postData.items.length?postData.items.map(postCard).join(''):empty('💬','첫 번째 이야기를 남겨보세요','아직 등록된 게시물이 없습니다.')}</div><aside><div class="side-card"><h3>커뮤니티 소개</h3><p>${E(c.description)}</p><p>${E(c.region)} · ${c.official?'공식 등록 확인':'일반 주민모임'}</p><button class="btn btn-outline btn-small" data-action="verification" data-id="${id}">조합 관련 인증 요청</button></div><div class="side-card"><h3>Google 블로그 게시판</h3><p>공개 Blogger 글을 이 모임에서 함께 볼 수 있어요. 링크는 자동 소유 인증되지 않습니다.</p>${c.blog_url?`<a class="inline-link" href="${A(c.blog_url)}" target="_blank" rel="noopener noreferrer">연결된 공개 블로그 ↗</a><button class="btn btn-soft btn-small" style="margin-top:12px" data-action="blog-community-preview" data-id="${id}">공개 글 불러오기</button><div id="community-blog-items"></div>`:`<p class="muted">아직 연결된 블로그가 없습니다.</p>`}${STATE.user?.id===c.owner_id?`<button class="btn btn-outline btn-small" style="margin-top:12px" data-action="blog-community-modal" data-id="${id}">${c.blog_url?'블로그 주소 수정':'블로그 연결하기'}</button>`:''}</div><div class="side-card"><h3>이야기를 널리 알려주세요</h3><p>게시판 주소를 공유하면 친구들과 바로 연결할 수 있어요.</p><button class="btn btn-soft btn-small" data-action="copy-url">🔗 링크 복사하기</button></div><div class="side-card"><h3>게시판 이용 수칙</h3><p>실명, 연락처, 주민등록번호, 조합원 명부, 검증되지 않은 비방성 내용은 공개하지 마세요. 신고 기능으로 운영자 검토를 요청할 수 있습니다.</p></div></aside></div></div>`;return}
 const [comms,posts]=await Promise.all([api('/communities'),api('/posts?limit=8')]);STATE.communities=comms.items;main.innerHTML=headerPage('동네에서 시작하는 연결','이웃들이 모여 질문하고 정보를 공유하는 우리 동네 디지털 사랑방입니다.','NEIGHBORHOOD COMMUNITY')+`<div class="shell page-body"><div class="section-header"><div><h2>우리 동네 커뮤니티</h2><p>주민모임을 탐색하거나 직접 만들어보세요.</p></div><button class="btn btn-primary" data-action="create-community">＋ 모임 만들기</button></div><div class="community-grid">${comms.items.map(communityCard).join('')}</div><div class="section-header" style="margin-top:55px"><div><h2>이웃들의 최근 이야기</h2><p>모두가 만드는 소통 공간입니다.</p></div><a class="inline-link" href="/feed" data-nav="feed">전체 게시판 보기 ↗</a></div><div class="feed-layout"><div>${posts.items.map(postCard).join('')}</div><aside><div class="side-card"><h3>커뮤니티의 약속</h3><p>서로 존중하고, 정보의 출처를 표시하며, 확인되지 않은 사실을 단정하지 않습니다.</p><a class="inline-link" href="/guide" data-nav="guide">법률·정책 알아보기 →</a></div></aside></div></div>`;
}
function postCard(p){return `<article class="post-card"><div class="post-head"><div class="user-avatar">${E((p.nickname||p.author_label||'R')[0])}</div><div><strong style="color:#3c6655">${E(p.nickname||p.author_label||'회원')}</strong><br>${E(p.community_name||'동네 광장')} · ${formatDate(p.created_at)}</div><span class="pill ${p.kind==='question'?'navy':p.demo?'orange':'gray'}" style="margin-left:auto">${p.demo?'예시':p.kind==='question'?(p.resolved?'답변 완료':'Q&A'):p.kind==='notice'?'공지':'소통'}</span></div><h3><a href="/post/${p.id}" data-nav="post">${E(p.title)}</a></h3><p>${E(p.body)}</p><div class="post-actions"><button class="action-chip ${p.liked?'active':''}" data-action="like" data-id="${p.id}">♡ ${p.like_count||0}</button><a class="action-chip" href="/post/${p.id}" data-nav="post">▤ 댓글 ${p.comment_count||0}</a><button class="action-chip ${p.bookmarked?'active':''}" data-action="bookmark" data-id="${p.id}">♧ 저장</button><button class="action-chip right" data-action="share-post" data-id="${p.id}">↗ 공유</button><button class="action-chip" data-action="report" data-id="${p.id}">⋯ 신고</button></div></article>`}
async function feedPage(){let data=await api('/posts?limit=100');STATE.posts=data.items;let communities=await api('/communities');main.innerHTML=headerPage('함께 만드는 열린 게시판','질문, 동네 이야기, 정책 정보를 자유롭게 나누세요.','RE:LAND SOCIAL FEED')+`<div class="shell page-body"><div class="feed-layout"><div><div class="feed-create"><div class="user-avatar">${STATE.user?E(STATE.user.nickname[0]):'✎'}</div><button data-action="write-post">지금 어떤 이야기를 나누고 싶으세요?</button></div><div class="tabs" id="post-tabs"><button class="tab active" data-action="post-filter" data-value="all">전체 이야기</button><button class="tab" data-action="post-filter" data-value="question">질문 · 답변</button><button class="tab" data-action="post-filter" data-value="discussion">동네 소식</button><button class="tab" data-action="post-filter" data-value="notice">공지사항</button></div><div id="feed-items">${data.items.length?data.items.map(postCard).join(''):empty('📝','아직 게시글이 없습니다','첫 게시글을 작성해 보세요.')}</div></div><aside><div class="side-card"><h3>관심 커뮤니티</h3>${communities.items.slice(0,4).map(c=>`<a style="display:block;padding:8px 0;font-size:12px;color:#38675a" href="/community/${c.id}" data-nav="community">▸ ${E(c.name)}</a>`).join('')}</div><div class="side-card"><h3>안전한 정보 공유</h3><p>출처 없는 진행 단계, 허위 보상금 계산, 제3자 개인정보 게시를 삼가세요. 광고성 글은 운영 정책에 따라 제한될 수 있습니다.</p></div></aside></div></div>`}
async function postPage(id){let d=await api('/posts/'+id);let p=d.item;main.innerHTML=headerPage('동네 이야기',`${E(p.community_name)} · ${formatDate(p.created_at)}`,'COMMUNITY Q&A')+`<div class="shell page-body"><div class="details-grid"><div><div class="post-card"><div class="post-head"><div class="user-avatar">✎</div><div>${E(p.nickname||p.author_label||'회원')}<br>${formatDate(p.created_at)}</div><span class="pill" style="margin-left:auto">${p.kind==='question'?(p.resolved?'답변 완료':'질문'):p.kind==='notice'?'공지':'일반'}</span></div><h2 style="font-size:26px;margin:25px 0">${E(p.title)}</h2><p style="display:block;white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:2.1;color:#3e5d50">${E(p.body)}</p><div class="post-actions"><button class="action-chip" data-action="like" data-id="${p.id}">♡ 좋아요</button><button class="action-chip" data-action="share-post" data-id="${p.id}">↗ 링크 공유</button>${STATE.user?.id===p.author_id&&p.kind==='question'?`<button class="action-chip" data-action="resolve" data-id="${p.id}">${p.resolved?'↺ 답변 완료 취소':'✓ 답변 완료 표시'}</button>`:''}${STATE.user?.id===p.author_id?`<button class="action-chip" data-action="delete-post" data-id="${p.id}">삭제</button>`:''}<button class="action-chip right" data-action="report" data-id="${p.id}">신고</button></div></div><div class="panel"><h3>답변과 댓글 ${d.comments.length}</h3>${d.comments.map(c=>`<div style="padding:15px 0;border-top:1px solid #edf1ed"><strong>${E(c.nickname)}</strong><span class="muted" style="font-size:10px;margin-left:10px">${formatDate(c.created_at)}</span><p style="white-space:pre-wrap;font-size:13px;margin-top:10px">${E(c.body)}</p></div>`).join('')||'<p class="muted">아직 답변이 없습니다. 첫 댓글을 남겨보세요.</p>'}<form id="comment-form" data-post-id="${id}"><label class="field"><span style="display:block;font-weight:800;margin-bottom:9px">댓글 작성</span><textarea name="body" class="form-control" style="width:100%" rows="3" minlength="2" maxlength="1600" required placeholder="존중하는 표현으로 답변해 주세요."></textarea></label><button type="submit" class="btn btn-primary">댓글 등록</button></form></div></div><aside><div class="side-card"><h3>커뮤니티로 돌아가기</h3><a class="btn btn-soft" href="/community/${p.community_id}" data-nav="community">${E(p.community_name)} ↗</a></div><div class="side-card"><h3>법률 답변 유의사항</h3><p>게시판의 일반 답변은 변호사의 개별 법률자문을 대체하지 않습니다. 분쟁과 기한은 공고문 및 자격 있는 전문가의 검토를 받으세요.</p><a class="inline-link" href="/experts" data-nav="experts">상담 문의하기 →</a></div></aside></div></div>`}
async function newsPage(){let data=await api('/news?limit=80');STATE.news=data.items;main.innerHTML=headerPage('오늘의 도시 변화 뉴스','주요 재개발·재건축 뉴스 제목과 원문 링크를 한 곳에서 확인하세요.','RE:LAND NEWSROOM')+`<div class="shell page-body"><div class="section-header"><div><h2>정비사업 뉴스 모아보기</h2><p>검색 RSS 제공 기사 · 최신 정보는 언론사 원문을 확인하세요.</p></div><span class="pill ${data.items.length?'':'orange'}">${data.items.length?'원문 링크 '+data.items.length+'건':'피드 연결 대기'}</span></div><div class="tabs" id="news-tabs">${['전체','재개발','정책','조합'].map((x,i)=>`<button class="tab ${i===0?'active':''}" data-action="news-filter" data-value="${x}">${x}</button>`).join('')}</div><div id="news-items" class="news-grid">${newsCards(data.items)}</div><div class="notice">Google 뉴스 검색 RSS를 활용해 기사 제목·발행처·원문 링크만 안내합니다. 검색 결과의 수집 시각은 기사 발행 시각과 다를 수 있습니다. 원문 저작권은 해당 언론사에 있습니다. ${data.last_attempt?'최근 수집 시도: '+formatDate(data.last_attempt):'처음 접속 시 백그라운드 동기화를 시도합니다.'}</div><div class="section-header" style="margin-top:45px"><div><h2>공식 정책·정보 채널</h2><p>기사와 별도로 정부·지자체 발표를 직접 확인하세요.</p></div></div><div class="grid-3">${[['국토교통부','https://www.molit.go.kr/','국가 정비사업 정책·보도자료'],['서울시 정비사업 정보몽땅','https://cleanup.seoul.go.kr/','조합·구역 추진현황과 정보공개'],['국가법령정보센터','https://www.law.go.kr/','최신 도시정비법 및 시행령']].map(x=>`<a class="feature-card" href="${A(x[1])}" target="_blank" rel="noopener noreferrer"><div class="feature-icon">↗</div><h3>${E(x[0])}</h3><p>${E(x[2])}</p><span class="inline-link">공식 사이트 방문 →</span></a>`).join('')}</div></div>`}
function newsCards(items){return items.length?items.map(n=>`<a class="news-card" href="${A(n.url)}" target="_blank" rel="noopener noreferrer"><div class="source"><span class="pill navy">${E(n.topic)}</span><span>${E(n.source)}</span></div><h3>${E(n.title)}</h3><p>${E(n.published||'발행일 미제공')} · 원문 바로가기 ↗</p></a>`).join(''):empty('📰','가져온 뉴스가 아직 없습니다','공개 RSS 수집이 가능한 서버 환경에서 자동 반영됩니다. 기사 발행일과 원문을 확인하지 못한 뉴스는 생성하지 않습니다.','<a class="btn btn-soft" href="https://news.google.com/search?q=%EC%9E%AC%EA%B0%9C%EB%B0%9C" target="_blank" rel="noopener noreferrer">Google 뉴스 검색 열기 ↗</a>')}
const LAW_LINK='https://www.law.go.kr/LSW/lsInfoP.do?lsiSeq=284065';
const GUIDES=[
 {name:'정비구역 지정',desc:'해당 지역이 어떤 기준과 계획으로 정비구역에 지정되는지 확인하는 단계입니다.',points:['정비계획 수립·주민공람·고시 여부 확인','정비구역 경계와 사업유형 확인','토지등소유자와 세입자에게 적용되는 내용 확인']},
 {name:'추진위원회',desc:'조합 설립을 위한 추진 조직의 구성 및 운영 관련 단계입니다.',points:['추진위원회 승인과 운영규정','동의서 내용 및 추진위원회 공개자료','동의 철회·절차 등에 대한 법령 확인']},
 {name:'조합설립인가',desc:'법정 요건을 갖춘 조합의 설립인가와 조합원 관련 사항을 확인합니다.',points:['조합 정관·설립인가 고시','조합원 자격과 동의 요건 검토','정기총회 의사록 및 자료 공개']},
 {name:'사업시행인가',desc:'사업 계획에 관해 인가받은 내용과 주요 권리관계를 살펴봅니다.',points:['사업시행계획인가 고시문 확인','건축계획·사업비·이주계획','열람·의견제출 기간과 대상 확인']},
 {name:'관리처분인가',desc:'분양 대상자, 권리가액, 분담금 등 중요사항이 구체화되는 과정입니다.',points:['분양신청 기간 및 대상','관리처분계획 공람·인가 확인','개인별 권리 관계는 전문가와 개별 검토']},
 {name:'이주·철거',desc:'이주 안내, 보상·이주비, 임대차·점유 관계 등을 살펴볼 단계입니다.',points:['주거·영업 세입자 해당 제도 확인','명도 및 이주 관련 기한 확인','보상 및 대출 조건을 개별 확인']},
 {name:'착공',desc:'공사 착수 및 진행 중 변경사항과 주민 안내사항을 확인합니다.',points:['착공신고 및 공정 안내','공사비 증액과 계약 변경 여부','안전·민원 안내 및 주요 공고 확인']},
 {name:'준공·이전고시',desc:'준공인가, 이전고시 및 권리 정리와 등기 절차 등을 살펴봅니다.',points:['준공인가 및 공사완료 고시','이전고시·등기 관련 일정 확인','최종 비용 정산·청산 관련 사항']}
];
async function guidePage(){main.innerHTML=headerPage('알아두면 든든한 재개발 법률·정책','복잡한 절차를 쉬운 말로 이해하고 공식 법령·고시를 확인하는 안내서입니다.','REDEVELOPMENT GUIDE')+`<div class="shell page-body"><div class="notice warn">중요: 아래 내용은 일반적인 학습·정보 안내이며 법률 의견이나 개별 권리의 확정적 판단이 아닙니다. 도시정비법은 개정될 수 있고, 사업유형·지역·고시일에 따라 적용 법령이 달라집니다.</div><div class="section-header"><div><span class="eyebrow">STEP BY STEP</span><h2>재개발 진행 흐름 한눈에</h2><p>기본적인 절차를 이해하기 위한 개요로, 모든 사업에 일률적으로 적용되지는 않습니다.</p></div></div><div class="guide-grid">${GUIDES.map((g,i)=>`<article class="guide-card"><div class="guide-num">STEP ${String(i+1).padStart(2,'0')} / 08</div><h3>${E(g.name)}</h3><p>${E(g.desc)}</p><ul>${g.points.map(x=>`<li>${E(x)}</li>`).join('')}</ul><a class="source-link" href="${LAW_LINK}" target="_blank" rel="noopener noreferrer">↗ 도시 및 주거환경정비법 확인하기</a></article>`).join('')}</div><div class="guide-callout"><div><h3>조합 운영 자료, 공개 의무를 확인하세요.</h3><p>도시정비법 제124조는 정비사업 관련 자료의 공개와 열람·복사에 관해 규정합니다. 공개대상·시기·방법 및 개인정보 관련 제한을 함께 확인하세요.</p></div><a class="btn btn-accent" href="https://www.law.go.kr/lsLinkCommonInfo.do?lsJoLnkSeq=1032611667" target="_blank" rel="noopener noreferrer">제124조 원문 보기 ↗</a></div><div class="section-header"><div><h2>자주 묻는 질문</h2><p>이해를 돕는 일반적인 설명입니다.</p></div></div><div class="faq-list">${[
 ['Google 계정으로 가입하면 조합원이 되나요?','아닙니다. 리랜드 계정과 주민모임 팔로우는 법적인 조합원 자격 및 조합 설립·의결과 무관합니다. 조합원 자격은 법령과 해당 사업 상황에 따라 별도로 판단해야 합니다.'],
 ['우리 구역의 진행 단계는 어디서 확인하나요?','국토교통부 공개 데이터, 지자체 고시, 해당 조합의 법정 정보공개 자료를 교차 확인해야 합니다. 리랜드의 지도와 연동 데이터는 최신 고시와 일치하지 않을 수 있습니다.'],
 ['분담금 계산을 사이트에서 할 수 있나요?','개인별 분담금은 권리가액, 사업비, 사업 추진 과정 등 복잡한 요소가 영향을 줍니다. 단순한 온라인 계산으로 확정 금액을 안내하지 않습니다.'],
 ['조합원 명부를 게시판에 올려도 되나요?','명부나 제3자의 연락처·주민등록번호 등을 게시판에 올리지 마세요. 자료 열람 권리와 인터넷 전체공개 가능 여부는 별개의 문제이며 개인정보법과 관련 제한을 검토해야 합니다.'],
 ['커뮤니티에서 받은 답변을 법률 자문으로 믿어도 되나요?','게시판 의견은 검증되지 않은 일반 정보일 수 있습니다. 의결, 소송, 이의신청, 분양신청 등 중요한 기한이 있는 사안은 공식 문서와 자격 있는 전문가에게 확인하세요.']].map(x=>`<details><summary>${E(x[0])}</summary><p>${E(x[1])}</p></details>`).join('')}</div><div style="text-align:center;padding-top:36px"><a class="btn btn-primary" href="/experts" data-nav="experts">내 상황에 대한 상담 문의하기 ↗</a></div></div>`}
async function expertsPage(){main.innerHTML=headerPage('상황에 맞는 상담의 시작','재개발·재건축 관련 궁금한 문제를 정리해 상담 접수를 신청할 수 있습니다.','LEGAL CONSULTATION',true)+`<div class="shell page-body"><div class="expert-layout"><div class="form-card"><h2>전문가 상담 접수</h2><p>개인정보·주민등록번호·상대방 명부를 기입하지 마세요. 제휴 전문가 배정은 현재 보장되지 않습니다.</p><form id="consultation-form"><div class="form-grid"><div class="field"><label for="consult-type">상담 분야 *</label><select id="consult-type" class="form-control" name="category" required>${['조합 설립·운영','조합원 자격','관리처분·분담금','이주·보상·명도','시공·계약분쟁','기타 정비사업 법률'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="consult-region">관련 지역 *</label><select id="consult-region" class="form-control" name="region" required>${REGIONS.filter(x=>x!=='전국').map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="field"><label for="consult-subject">문의 제목 *</label><input id="consult-subject" class="form-control" name="subject" minlength="5" maxlength="100" required placeholder="예: 관리처분인가 이후 이의 제기 가능 여부"></div><div class="field"><label for="consult-msg">상황 설명 *</label><textarea id="consult-msg" class="form-control" name="message" minlength="20" maxlength="3000" required placeholder="현재 사업 단계와 궁금한 점, 공식 안내서에 기재된 관련 날짜 등을 적어주세요."></textarea><small>20자 이상 · 최대 3,000자 / 불필요한 개인정보 입력 금지</small></div><label class="checkbox-row"><input type="checkbox" name="consent" required> <span>상담 접수 및 운영자 확인을 위한 문의 내용을 저장하고 처리하는 데 동의합니다. 전문기관이 연결된 경우 별도 동의를 받기 전에는 임의로 제3자에게 전달하지 않습니다.</span></label><button class="btn btn-primary" type="submit" style="width:100%">상담 문의 접수하기 →</button></form><div class="notice">상담 요청은 서비스에 저장됩니다. SMTP 알림이 설정되면 운영자에게 전달되지만, 제휴 전문가 계약·배정 및 답변 기한은 아직 제공되지 않습니다.</div></div><aside><div class="expert-visual"><strong>RE:LAND LEGAL DESK</strong></div><div class="expert-benefit"><h3>상담 전 확인하세요</h3><ul><li>정확한 정비사업 구역·사업유형</li><li>인가·공고·통지의 날짜</li><li>의견 제출·이의신청 등의 기한</li><li>정관·관리처분계획 등 공개 가능한 자료</li></ul></div><div class="side-card"><h3>긴급한 기한이 있나요?</h3><p>이의신청·소송·분양신청 등 법정 기간이 임박한 경우, 사이트 접수만 의존하지 말고 즉시 변호사 또는 관련 행정기관에 직접 확인하세요.</p><a class="inline-link" href="https://www.klac.or.kr/" target="_blank" rel="noopener noreferrer">대한법률구조공단 안내 ↗</a></div></aside></div></div>`}
async function profilePage(){if(!STATE.user){main.innerHTML=headerPage('내 활동 공간','Google 계정으로 시작해 보세요.')+`<div class="shell page-body">${empty('👋','로그인이 필요해요','내 프로필과 Google 블로그 링크를 관리할 수 있습니다.','<button class="btn btn-primary" data-action="login">로그인하기</button>')}</div>`;return}
 const u=STATE.user;const dash=await api('/my/dashboard');main.innerHTML=headerPage('내 리랜드',`${E(u.nickname)}님의 동네 이야기와 프로필입니다.`,'MY NEIGHBORHOOD')+`<div class="shell page-body"><div class="member-dashboard"><div class="member-score"><span class="mini-label">우리동네 활동 포인트</span><strong>${dash.engagement.score} P</strong><small>게임형 참여 지표 · 거래/조합자격과 무관</small></div><div class="member-badges"><b>획득 배지</b><div>${dash.engagement.badges.length?dash.engagement.badges.map(x=>`<span class="pill navy">🏅 ${E(x)}</span>`).join(''):'<span class="muted">첫 모임을 팔로우하거나 게시글을 작성해보세요.</span>'}</div><p>내 글 ${dash.engagement.counts.posts} · 댓글 ${dash.engagement.counts.comments} · 모임 팔로우 ${dash.engagement.counts.follows}</p></div></div><div class="panel watchlist"><div class="section-header"><div><h3>관심 정비구역</h3><p>공공 원본을 가져온 구역에서 관심등록할 수 있습니다.</p></div><a class="inline-link" href="/map" data-nav="map">지도 둘러보기 ↗</a></div>${dash.watches.length?dash.watches.map(x=>`<div class="watch-row"><a href="/district/${x.id}" data-nav="district"><strong>${E(x.name)}</strong> · ${E(x.province)} ${E(x.city)} · ${E(x.stage)}</a><button class="btn btn-outline btn-small" data-action="watch-district" data-id="${x.id}">관심 해제</button></div>`).join(''):'<p class="muted">아직 관심등록한 정비구역이 없습니다.</p>'}<h3 style="margin-top:26px">관심 구역 변경 내역</h3>${dash.changes.length?dash.changes.map(x=>`<p class="change-row"><a href="/district/${x.district_id}" data-nav="district">${E(x.name)}</a> ${E(x.old_stage)} → <strong>${E(x.new_stage)}</strong> <small>원본 기준일 ${E(x.source_date)}</small></p>`).join(''):'<p class="muted">관심등록 이후 감지된 공식 CSV의 단계 변경 내역이 없습니다.</p>'}<h3 style="margin-top:26px">나의 전문가 상담 접수</h3>${dash.consultations.length?dash.consultations.map(x=>`<p class="change-row">#${x.id} ${E(x.subject)} <span class="pill">${E(x.status)}</span></p>`).join(''):'<p class="muted">접수한 상담이 없습니다.</p>'}</div><div class="details-grid"><div class="form-card"><h2>내 프로필</h2><p>Google 로그인 계정을 기반으로 사용자 프로필을 관리합니다.</p><form id="profile-form"><div class="field"><label>표시 이름</label><input class="form-control" name="nickname" value="${E(u.nickname)}" minlength="2" maxlength="32" required></div><div class="field"><label>한 줄 소개</label><input class="form-control" name="bio" value="${E(u.bio)}" maxlength="180" placeholder="동네에 대한 관심을 소개해보세요."></div><div class="field"><label>내 Google 블로그 주소 (Blogger)</label><input class="form-control" name="blog_url" value="${E(u.blog_url)}" placeholder="https://myblog.blogspot.com/"><small>공개 블로그 링크 등록 기능입니다. 블로그 소유권 인증·자동 발행·비공개 글 접근 기능은 제공하지 않습니다.</small></div><button class="btn btn-primary" type="submit">프로필 저장하기</button></form>${u.blog_url?`<div style="margin-top:19px"><a class="inline-link" href="${A(u.blog_url)}" target="_blank" rel="noopener noreferrer">등록한 블로그 방문 ↗</a><button class="btn btn-soft btn-small" data-action="blog-preview">공개 게시물 확인</button><div id="blog-items"></div></div>`:''}</div><aside><div class="side-card"><h3>계정 안내</h3><p>로그인용 Google 고유 식별자와 기본 프로필로 인증합니다. Google 블로그 운영 권한은 별도로 요청하지 않습니다.</p><button class="btn btn-outline" data-action="logout">로그아웃</button><button class="btn btn-small" style="color:#9b3333;background:#fff0ef;margin-left:8px" data-action="delete-account-modal">회원 탈퇴</button></div><div class="side-card"><h3>커뮤니티 시작하기</h3><p>이웃과 함께 소식과 정보를 나눌 동네모임을 만들어 보세요.</p><button class="btn btn-soft" data-action="create-community">＋ 새 모임 만들기</button></div></aside></div></div>`}
async function sourcesPage(){main.innerHTML=headerPage('데이터·지도 출처 안내','정보의 기준일·위치 정밀도·이용허락 범위를 명확히 표시합니다.','DATA TRANSPARENCY')+`<div class="shell page-body"><div class="grid-2"><div class="panel"><span class="pill">공공 원본 · 가져오기 가능</span><h3 style="margin-top:13px">국토교통부 전국 도시정비사업 통합 데이터</h3><p class="muted" style="font-size:12px">2026-05-18 기준 / 공개 목록 1,566행 / 시도·시군구·구역명·추진단계·사업유형·사업시행자·공급 예정 세대수. 다운로드 원본 파일 CSV를 정제 후 앱에 가져올 수 있습니다.</p><a class="source-link" href="https://www.data.go.kr/data/15160169/fileData.do" target="_blank" rel="noopener noreferrer">원본 제공 사이트 ↗</a></div><div class="panel"><span class="pill">추가 검증 필요</span><h3 style="margin-top:13px">행정구역 중심점과 구역 경계</h3><p class="muted" style="font-size:12px">전국 통합 원본에 좌표·구역 폴리곤은 없습니다. 행정구역 중심점을 정비구역 실제 위치로 오인하지 않도록 precision 값으로 구분합니다. 경계는 지자체 고시 공간정보와 좌표계를 확인한 후 도입해야 합니다.</p><a class="source-link" href="https://www.vworld.kr/" target="_blank" rel="noopener noreferrer">VWorld 공간정보 플랫폼 ↗</a></div><div class="panel"><h3>정비사업 정보몽땅 / 서울 열린데이터광장</h3><p class="muted" style="font-size:12px">서울시 정비사업 고시·공개자료와 통계 자료의 확인처입니다. 사이트 이용약관·API 정책·갱신 주기를 확인한 뒤 연결해야 합니다.</p><a class="source-link" href="https://cleanup.seoul.go.kr/" target="_blank" rel="noopener noreferrer">서울시 정비사업 정보몽땅 ↗</a><a class="source-link" href="https://data.seoul.go.kr/dataList/OA-22856/F/1/datasetView.do" target="_blank" rel="noopener noreferrer">서울 도시정비사업 통계 ↗</a></div><div class="panel"><h3>지도·뉴스·법령</h3><p class="muted" style="font-size:12px">지도: OpenStreetMap 기여자 및 Leaflet. 뉴스: Google 뉴스 RSS 제목과 링크. 법령: 국가법령정보센터. 지도 타일 대량 이용 시 타일 서버 정책 및 자체 호스팅을 검토해야 합니다.</p><a class="source-link" href="https://operations.osmfoundation.org/policies/tiles/" target="_blank" rel="noopener noreferrer">OSM 타일 사용 정책 ↗</a><a class="source-link" href="https://www.law.go.kr/" target="_blank" rel="noopener noreferrer">국가법령정보센터 ↗</a></div></div><div class="panel"><h3>관리자용 실제 원본 반영 절차</h3><p>공공데이터포털에서 공식 CSV를 내려받은 후 터미널에서 <code>python scripts/import_districts.py "경로/원본.csv"</code>를 실행하세요. 인코딩과 컬럼을 자동으로 확인하며 실제 사업명을 로드합니다. 지역 중심 좌표는 정밀 위치가 아닌 시·도 대표점으로 표시됩니다. 데이터 오입력 방지를 위해 관리자 업로드를 공개 게시판에서 허용하지 않습니다.</p><p class="muted" style="font-size:12px">데모 콘텐츠는 별도 표시됩니다. 공공데이터를 수입한 후에도 목록 전부가 지도에 정확한 위치로 표시됐다고 주장해서는 안 됩니다.</p></div></div>`}
async function privacyPage(){main.innerHTML=headerPage('개인정보·이용 안내','플랫폼 사용자들이 안전하게 소통하기 위한 기본 원칙입니다.','PRIVACY & SAFETY')+`<div class="shell page-body"><div class="policy-page"><h2>1. 서비스 성격</h2><p>리랜드는 민간에서 운영하는 재개발 정보·주민 커뮤니티 플랫폼 예시입니다. 정부·지자체·특정 정비조합의 공식 홈페이지가 아닙니다. 현행 법령과 고시를 대체하지 않습니다.</p><h2>2. 수집·저장 항목</h2><p>Google 인증 후 Google 계정의 내부 고유 식별자(sub), 표시이름, 이메일, 공개 프로필 이미지(제공된 경우)를 서버에 저장합니다. 작성한 게시물·댓글·팔로우·상담 접수 정보가 서비스 DB에 저장됩니다. 인증 원본 토큰은 장기 저장하지 않습니다. 로그인 세션은 HttpOnly 쿠키로 관리합니다.</p><h2>3. 커뮤니티 개인정보 보호</h2><p>실명 조합원 명부, 주민등록번호, 등기부 전체 사본, 제3자 휴대전화 번호 등 개인정보를 게시판에 올리지 마세요. 게시물은 운영자 신고·숨김 처리의 대상이 될 수 있습니다. 조합원 인증 요청은 접수 상태만 표시하고 실제 증빙 확인 절차는 별도로 준비되어야 합니다.</p><h2>4. Blogger 링크</h2><p>등록된 blogspot.com 주소는 단순 프로필 링크 및 공개 RSS 표시용입니다. 소유권 확인, Blogger API 계정 접근, OAuth 글 발행 권한은 이 버전에 포함되지 않습니다.</p><h2>5. 상담 자료와 보존</h2><p>상담 문의는 서버에 저장되며 운영자 알림 서버 설정이 있으면 지정된 운영자 메일로 전송될 수 있습니다. 이 버전에는 개인정보 열람·삭제 요청을 처리하는 고객센터 운영 체계가 마련되어 있지 않습니다. 실제 서비스 공개 전에는 개인정보처리방침, 보유기간, 수탁자, 문의처, 정보주체 권리 행사 절차를 사업자에 맞게 확정해야 합니다.</p><h2>6. 데이터 정정 및 법률의견</h2><p>공공자료는 기준일 이후 변경될 수 있습니다. 정비사업 관련 중요한 기한 및 권리관계는 해당 행정기관의 최신 공고 및 전문가 상담으로 확인하세요.</p></div></div>`}
function writePostModal(communityId){if(!ensureAuth())return;modal(`${modalTitle('동네에 이야기 남기기')}<p>궁금한 점을 물어보거나 동네 소식을 나누세요.</p><form id="post-form"><div class="field"><label>커뮤니티 *</label><select class="form-control" style="width:100%" name="community_id" required>${STATE.communities.map(c=>`<option value="${c.id}" ${+communityId===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select></div><div class="field"><label>글 유형</label><select class="form-control" style="width:100%" name="kind"><option value="question">질문 · 답변</option><option value="discussion">동네 이야기</option><option value="notice">일반 공지</option></select></div><div class="field"><label>제목 *</label><input class="form-control" style="width:100%" name="title" minlength="5" maxlength="120" required placeholder="질문이나 소식의 제목"></div><div class="field"><label>내용 *</label><textarea class="form-control" style="width:100%" name="body" minlength="10" maxlength="5000" rows="6" required placeholder="다른 사람의 개인정보를 입력하지 마세요."></textarea></div><button class="btn btn-primary" style="width:100%" type="submit">게시하기 →</button></form>`)}
function createCommunityModal(){if(!ensureAuth())return;modal(`${modalTitle('우리 동네 모임 만들기')}<p>친구들과 소식을 나눌 비공식 주민모임을 만들어요. 조합 공식 계정은 별도 확인 전까지 표시하지 않습니다.</p><form id="community-form"><div class="field"><label>모임 이름 *</label><input class="form-control" style="width:100%" name="name" minlength="3" maxlength="60" required placeholder="예: 우리 동네 재개발 이웃모임"></div><div class="field"><label>지역 *</label><select class="form-control" style="width:100%" name="region">${REGIONS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>모임 소개 *</label><textarea class="form-control" style="width:100%" name="description" minlength="8" maxlength="450" rows="4" required placeholder="어떤 이야기를 나누고 싶나요?"></textarea></div><button class="btn btn-primary" style="width:100%" type="submit">모임 만들기</button></form>`)}
function communityBlogModal(id){if(!ensureAuth())return;modal(`${modalTitle('우리 모임 Blogger 연결')}<p>공개 blogspot.com 주소만 등록할 수 있습니다. Google 블로그 소유권 또는 Google 계정 접근 권한을 확인하지 않습니다.</p><form id="community-blog-form" data-community="${id}"><div class="field"><label>공개 Blogger 주소</label><input class="form-control" style="width:100%" name="blog_url" placeholder="https://example.blogspot.com/"></div><button class="btn btn-primary" type="submit" style="width:100%">블로그 링크 저장하기</button></form>`)}
function accountDeleteModal(){if(!ensureAuth())return;modal(`${modalTitle('회원 탈퇴')}<div class="notice warn">탈퇴하면 세션, 댓글, 관심표시, 상담 요청 등이 삭제되며 게시글의 작성자는 익명화됩니다. 이 작업은 되돌릴 수 없습니다.</div><form id="delete-account-form"><label class="field">확인 문구 입력: <b>DELETE MY ACCOUNT</b><input class="form-control" style="width:100%;margin-top:9px" name="confirmation" required pattern="DELETE MY ACCOUNT" autocomplete="off"></label><button class="btn btn-primary" style="width:100%" type="submit">계정 영구 탈퇴</button></form>`)}
function verificationModal(communityId){if(!ensureAuth())return;modal(`${modalTitle('조합 관련 확인 요청')}<div class="notice warn">이 요청은 조합원 또는 조합 공식 대표 자격을 자동 인증하지 않습니다. 신분증·주민등록번호·등기부 사진은 제출하지 마세요.</div><form id="verification-form" data-community="${communityId}"><div class="field"><label>확인 요청 사유 *</label><textarea class="form-control" style="width:100%" name="note" minlength="10" maxlength="400" rows="4" required placeholder="확인을 원하는 목적과 연락 방식을 개인정보 없이 작성하세요."></textarea></div><button type="submit" class="btn btn-primary" style="width:100%">요청 접수</button></form>`)}
function reportModal(postId){if(!ensureAuth())return;modal(`${modalTitle('게시글 신고하기')}<p>개인정보 노출, 사칭, 허위정보 등의 사유가 있으면 운영자에게 알려주세요.</p><form id="report-form" data-post="${postId}"><div class="field"><label>신고 이유 *</label><textarea class="form-control" style="width:100%" name="reason" minlength="5" maxlength="240" rows="4" required></textarea></div><button class="btn btn-primary" style="width:100%" type="submit">신고 접수</button></form>`)}
async function handleAction(node){const a=node.dataset.action,id=+node.dataset.id;try{switch(a){case'login':STATE.user?go('/profile'):loginModal();break;case'expert-apply':applyExpertModal();break;case'studio-my':await studioMyStatus();break;case'studio-story':expertStoryModal();break;case'close-modal':closeModal();break;case'mobile-menu':document.querySelector('.header').classList.toggle('menu-open');break;case'search':go('/map');break;case'demo-login':{const d=await api('/auth/demo',{method:'POST'});STATE.user=d.user;updateLogin();closeModal();tip('로컬 체험 계정으로 로그인했습니다.');render();break}case'logout':await api('/auth/logout',{method:'POST'});STATE.user=null;updateLogin();tip('로그아웃했습니다.');go('/');break;case'my-profile':go('/profile');break;case'reload':render();break;case'search-region':go('/map?region='+encodeURIComponent(node.dataset.value));break;case'district':go('/district/'+id);break;case'watch-district':if(!ensureAuth())return;{let result=await api('/districts/'+id+'/watch',{method:'POST'});tip(result.watching?'관심 정비구역에 추가했습니다.':'관심 정비구역에서 제외했습니다.');render();}break;case'follow':if(!ensureAuth())return;await api('/communities/'+id+'/follow',{method:'POST'});tip('팔로우 상태가 변경되었습니다.');render();break;case'create-community':createCommunityModal();break;case'write-post':{if(!STATE.communities.length){const d=await api('/communities');STATE.communities=d.items}writePostModal(node.dataset.community);break}case'verification':verificationModal(id);break;case'blog-community-modal':communityBlogModal(id);break;case'blog-community-preview':{const d=await api('/communities/'+id+'/blog');document.querySelector('#community-blog-items').innerHTML=d.items.length?d.items.map(x=>`<p style="margin:12px 0;font-size:12px"><a class="inline-link" href="${A(x.url)}" target="_blank" rel="noopener noreferrer">${E(x.title)} ↗</a></p>`).join(''):'<p class="muted">공개 게시물이 없습니다.</p>';break}case'like':case'bookmark':if(!ensureAuth())return;await api('/posts/'+id+'/'+a,{method:'POST'});tip(a==='like'?'좋아요 상태를 변경했어요.':'저장 상태를 변경했어요.');render();break;case'report':reportModal(id);break;case'resolve':if(!ensureAuth())return;await api('/posts/'+id+'/resolve',{method:'POST'});tip('질문 상태를 변경했어요.');render();break;case'delete-post':if(!ensureAuth())return;if(confirm('게시글을 삭제할까요?')){await api('/posts/'+id,{method:'DELETE'});tip('게시글을 삭제했습니다.');go('/feed')}break;case'delete-account-modal':accountDeleteModal();break;case'share-post':await copyText(location.origin+'/post/'+id);break;case'copy-url':await copyText(location.href);break;case'news-filter':document.querySelectorAll('#news-tabs .tab').forEach(n=>n.classList.toggle('active',n===node));document.querySelector('#news-items').innerHTML=newsCards(STATE.news.filter(x=>node.dataset.value==='전체'||x.topic===node.dataset.value));break;case'post-filter':document.querySelectorAll('#post-tabs .tab').forEach(n=>n.classList.toggle('active',n===node));document.querySelector('#feed-items').innerHTML=STATE.posts.filter(x=>node.dataset.value==='all'||x.kind===node.dataset.value).map(postCard).join('')||empty('☁','이 분류의 게시글이 아직 없어요','첫 이야기를 나눠보세요.');break;case'blog-preview':{let d=await api('/blog/preview?url='+encodeURIComponent(STATE.user.blog_url));document.querySelector('#blog-items').innerHTML=d.items.length?d.items.map(x=>`<p style="font-size:12px"><a class="inline-link" href="${A(x.url)}" target="_blank" rel="noopener noreferrer">${E(x.title)} ↗</a></p>`).join(''):'<p class="muted">공개 게시물이 없습니다.</p>';break}}}catch(err){tip(err.message)}}
async function copyText(text){try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else{let input=document.createElement('textarea');input.value=text;document.body.appendChild(input);input.select();document.execCommand('copy');input.remove()}tip('공유 링크를 복사했습니다.')}catch{tip('링크를 복사하지 못했습니다. 주소를 직접 복사하세요.')}}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
async function handleForm(form){let name=form.id,v=formData(form);try{switch(name){case'studio-search-form':go('/columns?q='+encodeURIComponent(v.q||''));break;case'studio-expert-filter':go('/directory?'+new URLSearchParams(v));break;case'studio-story-form':{const d=await api('/studio/experts/stories',{method:'POST',body:v});closeModal();tip('원고 #'+d.id+' 심사 요청이 접수됐습니다.');break}case'studio-expert-apply':{v.consent=!!form.querySelector('[name=consent]').checked;const d=await api('/studio/experts/apply',{method:'POST',body:v});closeModal();modal(`${modalTitle('전문가 등록 심사 접수')}<p>접수번호 #${d.id}입니다. 자격증·등록번호 등은 운영자가 별도 공식 경로로 확인해야 합니다. 확인 전 프로필은 공개되지 않습니다.</p><button class="btn btn-primary" data-action="close-modal">확인</button>`);break}case'community-blog-form':await api('/communities/'+form.dataset.community+'/blog',{method:'PUT',body:v});closeModal();tip('공개 Blogger 링크를 등록했습니다.');render();break;case'delete-account-form':await api('/auth/account',{method:'DELETE',body:v});STATE.user=null;closeModal();updateLogin();tip('계정 탈퇴가 처리되었습니다.');go('/');break;case'hero-search':go('/map?q='+encodeURIComponent(v.q));break;case'map-filter':go('/map?'+new URLSearchParams(v));break;case'community-form':{let d=await api('/communities',{method:'POST',body:v});closeModal();tip('새 동네 커뮤니티를 만들었습니다.');go('/community/'+d.id);break}case'post-form':{v.community_id=+v.community_id;let d=await api('/posts',{method:'POST',body:v});closeModal();tip('게시글이 등록됐습니다.');go('/post/'+d.id);break}case'comment-form':await api('/posts/'+form.dataset.postId+'/comments',{method:'POST',body:v});tip('답변이 등록되었습니다.');render();break;case'profile-form':await api('/auth/profile',{method:'PUT',body:v});STATE.user=(await api('/auth/me')).user;updateLogin();tip('프로필을 저장했습니다.');render();break;case'consultation-form':{v.consent=!!form.querySelector('[name=consent]').checked;let d=await api('/consultations',{method:'POST',body:v});form.reset();modal(`${modalTitle('상담 문의가 접수됐습니다')}<div class="notice">접수번호 #${d.id}</div><p>문의 내용이 저장되었습니다. 이 단계는 전문가 배정이나 답변 약속이 아닙니다. 법정 기한이 있다면 직접 전문가를 찾거나 관할기관에 문의하세요.</p><button class="btn btn-primary" data-action="close-modal" style="width:100%">확인</button>`);break}case'verification-form':await api('/communities/'+form.dataset.community+'/verification',{method:'POST',body:v});closeModal();tip('조합 관련 확인 요청이 접수됐습니다.');break;case'report-form':await api('/posts/'+form.dataset.post+'/report',{method:'POST',body:v});closeModal();tip('신고가 접수됐습니다.');break}}catch(err){if(err.message.includes('로그인'))loginModal();else tip(err.message)}}
document.addEventListener('click',async event=>{const link=event.target.closest('a[data-nav]');if(link){event.preventDefault();go(link.getAttribute('href'));return}const action=event.target.closest('[data-action]');if(action){event.preventDefault();await handleAction(action);return}if(event.target.id==='modal')closeModal()});
document.addEventListener('submit',async event=>{if(event.target.id){event.preventDefault();await handleForm(event.target)}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if((event.key==='Enter'||event.key===' ')&&event.target.classList.contains('result-row')){event.preventDefault();handleAction(event.target)}});
window.addEventListener('popstate',render);
initialize();
if('serviceWorker' in navigator && location.protocol==='https:') navigator.serviceWorker.register('/static/sw.js').catch(()=>{});

/* RE:LAND Legal Studio v2 — appended to app.js at package build. */
function studioHead(title,sub,eyebrow='RE:LAND LEGAL STUDIO'){return headerPage(E(title),E(sub),eyebrow)}
function studioTile(a){return `<a href="/column/${a.id}" data-nav="column" class="studio-card"><div class="studio-image"><img loading="lazy" src="${E(a.image)}" alt="${E(a.image_alt)}"></div><div class="studio-card-content"><span class="studio-kicker">${E(a.category)} · ${E(a.law_article)}</span><h3>${E(a.title)}</h3><p>${E(a.description)}</p><div class="studio-meta"><span>법률 감수 전 편집 초안</span><b>내용 확인 ↗</b></div></div></a>`}
async function columnsPage(){const params=new URLSearchParams(location.search);const page=Math.max(1,+params.get('page')||1);const cat=params.get('category')||'';const q=params.get('q')||'';
 const d=await api('/studio/columns?'+new URLSearchParams({page,limit:12,category:cat,q}));
 main.innerHTML=studioHead('리랜드 재개발 법률 저널','도시정비법, 조합설립, 관리처분, 공개자료, 등기까지. 120편의 주제별 편집 원고와 확인된 법제처 조문 링크를 제공합니다.')+`<section class="shell studio-main"><div class="studio-warning"><strong>법률 전문 검수 이전의 편집 초안입니다.</strong> 실제 구역·당사자의 권리판단이 아니며 법령 시행일과 공고 원문을 다시 확인하세요. AI 생성 이미지는 실제 현장 사진이나 확정 조감도가 아닙니다.</div><div class="studio-tools"><form id="studio-search-form"><input name="q" value="${E(q)}" class="form-control" placeholder="법률·정비사업 주제 검색" aria-label="칼럼 검색"><button class="btn btn-primary" type="submit">검색</button></form><select class="form-control" id="studio-category" aria-label="주제 선택"><option value="">전체 주제</option>${d.categories.map(x=>`<option value="${E(x)}" ${cat===x?'selected':''}>${E(x)}</option>`).join('')}</select></div><div class="studio-heading"><div><span class="eyebrow">THE LAW REVIEW</span><h2>자료와 법령을 함께 읽는 120편의 안내서</h2></div><b>${d.total}편 표시</b></div><div class="studio-grid">${d.items.map(studioTile).join('')||'<p>조건에 맞는 글이 없습니다.</p>'}</div><div class="studio-pagination">${page>1?`<a class="btn btn-soft" data-nav="columns" href="/columns?${new URLSearchParams({page:page-1,category:cat,q})}">← 이전</a>`:''}<span>${page} / ${Math.ceil(d.total/12)||1}</span>${page*12<d.total?`<a class="btn btn-primary" data-nav="columns" href="/columns?${new URLSearchParams({page:page+1,category:cat,q})}">다음 →</a>`:''}</div></section>`;}
async function columnPage(id){const a=await api('/studio/columns/'+id);main.innerHTML=studioHead(a.category,a.title,'LEGAL REVIEW · '+a.law_article)+`<section class="shell studio-article"><article><div class="studio-article-hero"><img src="${E(a.image)}" alt="${E(a.image_alt)}"><span>AI 생성 설명용 콘셉트 이미지 · 실제 정비사업장 사진 아님</span></div><div class="studio-warning"><b>법률 전문가 감수 전 편집 초안 · ${E(a.date)} 기준</b><p>이 글은 일반 교육 정보를 제공합니다. 법적 기한·권리관계 등은 반드시 관할 기관의 최신 고시 및 자격 있는 전문가의 확인이 필요합니다.</p></div><div class="studio-article-copy"><span class="studio-kicker">${E(a.category)} · RE:LAND ORIGINAL JOURNAL</span><h1>${E(a.title)}</h1>${a.body.split('\n\n').map(x=>`<p>${E(x)}</p>`).join('')}<div class="studio-law"><span>법제처 공식 원문 발췌</span><h3>${E(a.law_name)} ${E(a.law_article)} (${E(a.law_heading)})</h3><blockquote>${E(a.law_excerpt)}…</blockquote><a href="${A(a.law_url)}" target="_blank" rel="noopener noreferrer">국가법령정보센터에서 조문 전체 원문과 시행일 확인 ↗</a><small>발췌는 전체 조문이 아닙니다. 수정·폐지 여부와 부칙을 반드시 다시 확인하세요.</small></div><div class="studio-links"><a class="btn btn-soft" href="/columns" data-nav="columns">← 전체 칼럼</a><a class="btn btn-primary" href="/directory" data-nav="directory">관련 전문가 디렉터리 →</a></div></div></article></section>`}
function expertCard(x){return `<article class="studio-expert"><div class="studio-expert-top"><div class="studio-monogram">${E((x.name||'전')[0])}</div><div><span class="studio-kicker">${E(x.profession)} · ${E(x.region)}</span><h3>${E(x.name)} <small>${E(x.office)}</small></h3></div>${x.sponsored?'<span class="studio-ad">광고</span>':''}</div><p>${E(x.introduction)}</p><div class="studio-expertise">${E(x.expertise)}</div><a class="btn btn-soft" href="/expert/${x.id}" data-nav="expert">프로필 · 글 · 공식 연락처 보기 →</a></article>`}
async function directoryPage(){const params=new URLSearchParams(location.search);const profession=params.get('profession')||'';const region=params.get('region')||'';const q=params.get('q')||'';const d=await api('/studio/experts?'+new URLSearchParams({profession,region,q}));
 main.innerHTML=studioHead('정비사업 전문가 네트워크','변호사 · 법무사 · 행정사가 자신의 콘텐츠와 공식 연락 채널을 소개하는 공간입니다. 등록과 광고를 구별합니다.')+`<section class="shell studio-main"><div class="studio-expert-banner"><div><span>PARTNER WITH RE:LAND</span><h2>좋은 콘텐츠가 전문가에게 연결되는 플랫폼</h2><p>자격을 확인한 전문가의 칼럼·Blogger·Shorts를 주민이 직접 읽고 공식 연락처를 선택합니다. 유료 광고는 광고로 표시하며 사건 알선 수수료는 받지 않습니다.</p><button class="btn btn-accent" data-action="expert-apply">전문가 입점 신청하기 →</button><a href="/partners" data-nav="partners" class="btn btn-soft" style="margin-left:8px">입점·광고 제안 보기</a> ${STATE.user?'<button class="btn btn-soft" style="margin-left:8px" data-action="studio-my">내 등록·칼럼 관리</button>':''}</div><div class="studio-banner-icon">⚖</div></div><div class="studio-tools"><form id="studio-expert-filter"><input class="form-control" name="q" placeholder="이름·사무소·분야" value="${E(q)}"><select class="form-control" name="profession"><option value="">전체 전문직</option>${['변호사','법무사','행정사'].map(x=>`<option ${x===profession?'selected':''}>${x}</option>`).join('')}</select><select class="form-control" name="region"><option value="">전체 지역</option>${REGIONS.slice(1).map(x=>`<option ${x===region?'selected':''}>${x}</option>`).join('')}</select><button class="btn btn-primary">검색</button></form></div><div class="studio-heading"><h2>검토된 전문가 소개</h2><b>${d.items.length}명</b></div><div class="studio-grid">${d.items.map(expertCard).join('')||empty('⚖️','공개 승인된 전문가가 아직 없습니다','가상의 변호사 이름이나 검증되지 않은 자격·연락처는 게시하지 않습니다.','<button class="btn btn-primary" data-action="expert-apply">첫 전문가로 입점 신청</button>')}</div><div class="studio-note">광고상품은 법령·직역별 광고규정 심사를 거쳐야 판매할 수 있습니다. 유료 노출은 광고로 표시되며 검색순위나 자격 인증을 의미하지 않습니다.</div></section>`;}
async function expertDetailPage(id){const d=await api('/studio/experts/'+id);const x=d.expert;api('/studio/experts/'+id+'/event?event=profile_view',{method:'POST'}).catch(()=>{});
 const link=(label,url,event)=>url?`<a class="btn btn-soft studio-ext" href="${A(url)}" target="_blank" rel="noopener noreferrer" data-expert-event="${event}" data-expert-id="${id}">${label} ↗</a>`:'';
 main.innerHTML=studioHead(x.name+' '+x.profession,x.office+' · '+x.region)+`<section class="shell studio-main"><div class="studio-profile"><div class="studio-monogram huge">${E(x.name[0])}</div><div class="studio-profile-copy"><span class="studio-kicker">${E(x.profession)} · ${E(x.region)}</span><h1>${E(x.name)}</h1><h3>${E(x.office)}</h3><p>${E(x.introduction)}</p><p><b>주요 업무:</b> ${E(x.expertise)}</p><div class="studio-links">${x.phone?`<a href="tel:${E(x.phone.replace(/[^0-9+]/g,''))}" class="btn btn-primary" data-expert-event="phone_click" data-expert-id="${id}">공개 사무소 전화하기</a>`:''}${x.public_email?`<a class="btn btn-soft" href="mailto:${E(x.public_email)}" data-expert-event="email_click" data-expert-id="${id}">공개 사무소 이메일 ↗</a>`:''}${link('사무소 공식 사이트',x.website,'official_website_click')}${link('Google Blogger',x.blogger,'blog_click')}${link('YouTube 채널',x.youtube,'youtube_click')}</div><small>${E(x.credential_notice)}</small><p class="studio-note">프로필을 열람하거나 연락하는 행위는 RE:LAND가 사건을 배정·알선함을 의미하지 않습니다. 상담계약은 당사자와 전문가가 직접 체결합니다.</p></div></div><h2 style="margin-top:35px">전문가 직접 작성 칼럼</h2><div class="studio-grid">${d.stories.map(y=>`<article class="studio-expert"><h3>${E(y.title)}</h3><p>${E(y.summary)}</p><a href="${A(y.law_url)}" target="_blank" rel="noopener noreferrer">관련 법령 원문 ↗</a></article>`).join('')||'<p>운영자 검수를 통과한 공개 칼럼이 아직 없습니다.</p>'}</div></section>`;}
async function shortsPage(){const d=await api('/studio/videos');main.innerHTML=studioHead('재개발 법률 Shorts 큐레이션','조합·절차·이주·관리처분 정보를 설명하는 전문가 영상을 모읍니다. 저작권과 YouTube 표기 기준을 준수합니다.')+`<section class="shell studio-main"><div class="studio-warning">검수된 공개 YouTube 영상만 등록합니다. 가상 영상·조회수·허위 전문가 증언은 게시하지 않습니다. YouTube 플레이어의 원래 기능을 유지합니다.</div><div class="studio-grid">${d.items.map(v=>`<article class="studio-expert"><div class="studio-video"><iframe loading="lazy" src="https://www.youtube-nocookie.com/embed/${E(v.video_id)}" title="${E(v.title)}" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"></iframe></div><div class="studio-card-content"><span class="studio-kicker">${E(v.category)} · ${E(v.creator)}</span><h3>${E(v.title)}</h3><p>${E(v.source_disclaimer)}</p><a target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/watch?v=${E(v.video_id)}">YouTube에서 보기 ↗</a></div></article>`).join('')||empty('▶️','검수된 Shorts를 등록하는 중입니다','실제 YouTube URL과 게시자 정보를 관리자가 확인한 뒤 등록할 수 있습니다. 샘플 영상은 사실처럼 표시하지 않습니다.','<a href="/columns" class="btn btn-primary" data-nav="columns">법률 저널 읽기</a>')}</div></section>`;}
function applyExpertModal(){if(!ensureAuth())return;modal(`${modalTitle('전문가 입점 신청')}<p>변호사·법무사·행정사의 등록정보를 수동 심사합니다. Google 로그인만으로 전문자격이 인증되지는 않습니다. 공개 프로필·콘텐츠·연락처를 직접 입력하세요.</p><form id="studio-expert-apply"><div class="field"><label>직역 *</label><select name="profession" class="form-control" required>${['변호사','법무사','행정사'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>실명 *</label><input name="name" class="form-control" minlength="2" maxlength="65" required></div><div class="field"><label>사무소명 *</label><input name="office" class="form-control" minlength="2" maxlength="100" required></div><div class="field"><label>활동 지역</label><select name="region" class="form-control">${REGIONS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>주요 업무 *</label><input name="expertise" class="form-control" minlength="3" maxlength="300" placeholder="도시정비법, 관리처분 분쟁" required></div><div class="field"><label>전문가 소개 *</label><textarea name="introduction" class="form-control" minlength="30" maxlength="1800" required></textarea></div><div class="field"><label>자격 확인 참고정보 (민감 정보 입력 금지)</label><input name="license_note" class="form-control" maxlength="300" placeholder="공식 조회 가능한 자격·등록정보"></div><div class="field"><label>공개 전화</label><input name="phone" class="form-control" maxlength="30"></div><div class="field"><label>공개 이메일</label><input name="public_email" class="form-control" type="email"></div><div class="field"><label>공식 HTTPS 사이트</label><input name="website" class="form-control" type="url"></div><div class="field"><label>Google 블로그(blogspot.com)</label><input name="blogger" class="form-control" type="url"></div><div class="field"><label>YouTube 채널</label><input name="youtube" class="form-control" type="url"></div><label class="checkbox-row"><input type="checkbox" name="consent" required> 입력한 연락처·소개 정보가 공개될 수 있으며, 운영자 심사에 동의합니다.</label><button class="btn btn-primary" type="submit">심사 신청 접수</button></form>`)}

document.addEventListener('change',event=>{if(event.target.id==='studio-category'){let v=event.target.value;go('/columns?'+new URLSearchParams({category:v}))}});document.addEventListener('click',event=>{const el=event.target.closest('[data-expert-event]');if(el){api('/studio/experts/'+el.dataset.expertId+'/event?event='+encodeURIComponent(el.dataset.expertEvent),{method:'POST'}).catch(()=>{})}});


/* Registered experts can submit original columns; every draft awaits moderation. */
async function studioMyStatus(){if(!ensureAuth())return;const data=await api('/studio/experts/mine');const x=data.expert;if(!x){applyExpertModal();return}const metrics=await api('/studio/experts/analytics');let measure=Object.entries(metrics.events).map(([k,v])=>`<span class="pill">${E(k)} ${v}</span>`).join(' ');modal(`${modalTitle('내 전문가 등록 현황')}<div class="notice"><strong>${E(x.name)} ${E(x.profession)}</strong><p>${E(x.office)}</p><p>접속·콘텐츠 지표 (비과금): ${measure||'아직 집계 없음'}</p><p>심사 상태: ${x.status==='approved'?'승인됨 · 프로필 공개':x.status==='pending'?'운영자 확인 대기':'검토 후 반려됨'}</p></div>${x.status==='approved'?'<button class="btn btn-primary" data-action="studio-story" style="width:100%">재개발 전문 칼럼 원고 제출 →</button>':'<p>전문 자격 및 직역 광고 적합성을 운영자가 검토한 후 공개됩니다.</p>'}`)}
function expertStoryModal(){if(!ensureAuth())return;modal(`${modalTitle('전문가 칼럼 제출')}<p>본인 저작의 원고만 제출하세요. 법률정보에는 근거법 조문과 정확한 발효일을 표시하고, 개인정보·특정 사건 비밀을 포함하지 마세요. 제출 후 운영자 승인 전까지 공개되지 않습니다.</p><form id="studio-story-form"><div class="field"><label>제목 *</label><input name="title" class="form-control" minlength="8" maxlength="120" required></div><div class="field"><label>요약 *</label><textarea name="summary" class="form-control" minlength="30" maxlength="500" required></textarea></div><div class="field"><label>전문 칼럼 원문 *</label><textarea name="body" class="form-control" minlength="100" maxlength="8000" style="min-height:210px" required></textarea></div><div class="field"><label>법제처 원문 URL</label><input name="law_url" class="form-control" type="url" placeholder="https://www.law.go.kr/..."></div><button class="btn btn-primary" type="submit">심사용 칼럼 제출 →</button></form>`)}

async function partnerPage(){main.innerHTML=studioHead('전문가 제휴·광고 파트너십','RE:LAND 정비사업 커뮤니티의 이용자에게 신뢰할 수 있는 전문 정보와 사무소 채널을 소개하세요.')+`<section class="shell studio-main"><div class="studio-expert-banner"><div><span>RE:LAND PARTNERSHIP PROGRAM</span><h2>전문성은 콘텐츠로, 연결은 독자의 선택으로</h2><p>전문가 프로필·원문 칼럼·공식 Blogger·YouTube Shorts를 연결합니다. 이용자의 실제 사건 수임을 보장하거나 수임 건당 수수료를 청구하지 않습니다.</p><button class="btn btn-accent" data-action="expert-apply">입점 신청하기 →</button></div><div class="studio-banner-icon">♜</div></div><div class="studio-grid">${[['무료 프로필','직역·사무소·활동지역·업무 소개, 공식 전화·사이트와 Blogger·YouTube 링크를 연결하는 공개 프로필'],['칼럼 파트너','원문 저작권자 동의 및 법률 근거를 갖춘 정보성 칼럼 제출, 승인형 콘텐츠 큐레이션'],['광고 협의형','광고 표시가 붙는 프로필 홍보와 단순 통계 리포트. 적법성 검토를 거친 별도 광고계약을 체결한 경우에만 운영']].map(([t,c],i)=>`<article class="studio-expert"><span class="studio-kicker">0${i+1} · PARTNER PRODUCT</span><h3>${t}</h3><p>${c}</p></article>`).join('')}</div><div class="studio-warning" style="margin-top:28px">변호사 등 전문직의 광고는 각 직역법 및 협회 광고규정이 적용됩니다. 정액 광고도 운영 구조에 따라 문제가 될 수 있으므로 법률 검토가 완료되기 전까지 실제 광고비 청구 기능을 활성화하지 않았습니다. 실인원·조회수 또는 수임 실적을 보장하지 않습니다.</div><a class="btn btn-soft" href="/directory" data-nav="directory">전문가 소개 페이지로 돌아가기 →</a></section>`;}
